_MINOR_WORDS = frozenset({"a", "an", "for", "in", "of", "on", "the", "to"})


def make_acronym(phrase: str) -> str:
    """
    Build an acronym from the words of a phrase.

    Words identified as minor words are represented by their first letter in lowercase,
    unless they are the first word of the phrase. All other words are represented by
    their first letter in uppercase.
    """
    words = tokenize_words(phrase)
    if not words:
        return ""

    letters = []
    for index, word in enumerate(words):
        if index > 0 and word.lower() in _MINOR_WORDS:
            letters.append(word[0].lower())
        else:
            letters.append(word[0].upper())
    return "".join(letters)
