        curr.append(w)
        if w not in abbr and term_re.search(w):
            if i + 1 < len(words) and next_re.match(words[i+1]):
                sentences.append(" ".join(curr))
                curr = []
    if curr:
        sentences.append(" ".join(curr))
    return sentences
